import{_ as a,o as e,c as o,a3 as r}from"./chunks/framework.BveOjhN0.js";const u=JSON.parse('{"title":"辅修结束，暑假正式开始","description":"人工智能辅修小学期正式结束，告别忙碌的课堂，迎来属于自己的暑假时光。","frontmatter":{"date":"2026-08-07T00:00:00.000Z","tags":["生活随笔"],"description":"人工智能辅修小学期正式结束，告别忙碌的课堂，迎来属于自己的暑假时光。","head":[["meta",{"property":"og:description","content":"人工智能辅修小学期正式结束，告别忙碌的课堂，迎来属于自己的暑假时光。"}],["meta",{"property":"og:title","content":"辅修结束，暑假正式开始"}]]},"headers":[],"relativePath":"posts/summer-vacation-begins.md","filePath":"posts/summer-vacation-begins.md"}'),n={name:"posts/summer-vacation-begins.md"};function i(s,t,l,p,c,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="辅修结束-暑假正式开始" tabindex="-1">辅修结束，暑假正式开始 <a class="header-anchor" href="#辅修结束-暑假正式开始" aria-label="Permalink to &quot;辅修结束，暑假正式开始&quot;">​</a></h1><p>今天是个值得纪念的日子——人工智能辅修的小学期课程全部结束，我也终于可以正式开启属于自己的暑假生活了。回望这段时间，忙碌却充实，现在终于能稍稍松一口气。</p><h2 id="辅修收官" tabindex="-1">辅修收官 <a class="header-anchor" href="#辅修收官" aria-label="Permalink to &quot;辅修收官&quot;">​</a></h2><p>从机器学习方法到计算机视觉，从机器人控制到最后的 Python 编程与实训课程，这段辅修之旅画上了句号。每一门课都让我对人工智能这个领域有了更深的理解，也让我看到了自己还有太多需要补足的地方。</p><p><strong>最后的两门课：</strong></p><ul><li><strong>人工智能与 Python 编程</strong>：让我体会到 Python 在 AI 领域的灵活与强大，许多复杂的逻辑用简洁的代码就能实现</li><li><strong>人工智能引领实训</strong>：把前面学到的知识真正串了起来，从问题定义到方案落地，完整走了一遍流程</li></ul><p><strong>最大的收获：</strong></p><ul><li>不再只是停留在&quot;听过&quot;的层面，而是能动手去实现一些简单的东西</li><li>对 AI 的全貌有了更清晰的认识，知道每个方向大概在做什么</li><li>也更清楚地看到了自己的短板，知道接下来该往哪里努力</li></ul><h2 id="暑假计划" tabindex="-1">暑假计划 <a class="header-anchor" href="#暑假计划" aria-label="Permalink to &quot;暑假计划&quot;">​</a></h2><p>辅修结束了，但学习不会停下。这个暑假，我给自己定下几个小目标：</p><ol><li><strong>复盘辅修内容</strong>：把课程中没完全吃透的知识点再过一遍，尤其是矩阵运算和深度学习相关的基础</li><li><strong>做一个小项目</strong>：选一个自己感兴趣的方向动手实践，把学过的东西用起来</li><li><strong>多读几本书</strong>：技术之外，也读一些让自己放松的书</li><li><strong>好好休息</strong>：毕竟忙了这么久，劳逸结合才能走得更远</li></ol><p>当然，计划归计划，暑假最珍贵的就是可以按照自己的节奏来安排时间，不用再被课表推着走。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>终于告别了连轴转的日子，迎来了可以自由支配的时光。希望接下来的两个月，能让自己既有所收获，也能好好放松一下。</p><p>今天正好是立秋，夏天的尾声悄悄到来。</p><p>祝大家立秋快乐！🍂</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>辅修结束是一个节点，但绝不是终点。带着这段时间的收获与遗憾，继续往前走就好。暑假，我来了。</p>',18)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
